-- Jeu de LecteurRejetsEncaissement et EcrivainRejetsEncaissement (« Rejets d'encaissement », PROC_REJET), lot 12 du plan-676a4b19.
-- Identifiants 22040xx (encaissements), 22041xx (ventilations), 22042xx (clients rec.Client), 22043xx (affaires), 22044xx (rejets).
-- Types : RIG_DEV (SSDT RigDatabase\dbo\Tables\ENCAISSEMENT.sql, VENTILATION.sql, ENCAISSEMENT_RECUS_REJETES.sql, MODE_PAIEMENT.sql,
-- INPI_REVERSEMENTS.sql) ; les tables ENCAISSEMENT, VENTILATION et MODE_PAIEMENT sont partagees avec PROC_RECHENC.sql et
-- PROC_REMBANQ.sql (meme forme, colonnes ajoutees NULLables). Les encaissements d'ici sont DATES DANS LE PASSE : ils n'entrent ni
-- dans « Encaissements » (le jour) ni dans « Remise en banque » (le jour) ; leurs modes ont un type que les autres n'ont pas (CH).
IF OBJECT_ID(N'v2.ENCAISSEMENT') IS NULL
    CREATE TABLE v2.ENCAISSEMENT (ENCMT_ID_ENCMT int NOT NULL PRIMARY KEY, ENCMT_MONTANT money NOT NULL, ENCMT_DATE_ENCAISSEMENT datetime NOT NULL,
        ENCMT_DESIGNATION_PAYEUR varchar(100) NULL, ENCMT_NUMERO_TITRE varchar(32) NULL, ENCMT_MODE_PAIEMENT varchar(8) NULL,
        ENCMT_DESIGNATION_BANQUE varchar(100) NULL, ENCMT_DATE_COMPTABILISATION datetime NULL, ENCMT_ID_UTLST int NULL,
        ENCMT_REMIS int NULL, ENCMT_COMMENTAIRE varchar(255) NULL);
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_ID_BANQU') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_ID_BANQU int NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_ORIGINE') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_ORIGINE varchar(3) NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_ID_ARRV') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_ID_ARRV int NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_COMPTE_BANCAIRE_REMIS') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_COMPTE_BANCAIRE_REMIS varchar(50) NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_GUID') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_GUID varchar(36) NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_RECU_ID_ADRBS') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_RECU_ID_ADRBS int NULL;
IF COL_LENGTH('v2.ENCAISSEMENT', 'ENCMT_EXT_SOURCE') IS NULL ALTER TABLE v2.ENCAISSEMENT ADD ENCMT_EXT_SOURCE varchar(5) NULL;
IF OBJECT_ID(N'v2.VENTILATION') IS NULL
    CREATE TABLE v2.VENTILATION (VENTI_ID_VENTI int NOT NULL PRIMARY KEY, VENTI_ID_PYEUR int NULL, VENTI_ID_ENCMT int NULL,
        VENTI_ID_AFFRE int NULL, VENTI_ID_CLIEN int NULL, VENTI_MONTANT money NOT NULL, VENTI_DATE_VENTILATION datetime NULL);
IF COL_LENGTH('v2.VENTILATION', 'VENTI_DATE_DEMANDE_TPG') IS NULL ALTER TABLE v2.VENTILATION ADD VENTI_DATE_DEMANDE_TPG datetime NULL;
IF OBJECT_ID(N'v2.MODE_PAIEMENT') IS NULL
    CREATE TABLE v2.MODE_PAIEMENT (R_MODEPAIEME_VALEUR varchar(8) NOT NULL PRIMARY KEY, R_MODEPAIEME_LIBELLE_ECRAN varchar(35) NOT NULL);
IF COL_LENGTH('v2.MODE_PAIEMENT', 'R_MODEPAIEME_UTILISABLE_SAISIE') IS NULL ALTER TABLE v2.MODE_PAIEMENT ADD R_MODEPAIEME_UTILISABLE_SAISIE bit NULL;
IF COL_LENGTH('v2.MODE_PAIEMENT', 'R_MODEPAIEME_TYPE') IS NULL ALTER TABLE v2.MODE_PAIEMENT ADD R_MODEPAIEME_TYPE varchar(3) NULL;
IF OBJECT_ID(N'v2.ENCAISSEMENT_RECUS_REJETES') IS NULL
    CREATE TABLE v2.ENCAISSEMENT_RECUS_REJETES (ENCRR_ID_ENCRR int NOT NULL PRIMARY KEY, ENCRR_NUM_TITRE varchar(32) NULL, ENCRR_DATE_CREATION datetime NOT NULL,
        ENCRR_DATE_ENCMT datetime NOT NULL, ENCRR_MONTANT money NOT NULL, ENCRR_RAISON_REJET varchar(150) NULL, ENCRR_DESIGNATION_BANQUE varchar(100) NULL,
        ENCRR_DESIGNATION_PAYEUR varchar(100) NULL, ENCRR_CLIENT varchar(255) NULL, ENCRR_CLIENT_ADRESSE varchar(255) NULL, ENCRR_CLIENT_EMAIL varchar(255) NULL);
IF OBJECT_ID(N'v2.INPI_REVERSEMENTS') IS NULL
    CREATE TABLE v2.INPI_REVERSEMENTS (INPIRV_ID_INPIRV int NOT NULL PRIMARY KEY, INPIRV_ID_PAYMENT varchar(50) NOT NULL, INPIRV_ID_ENCMT int NULL);
IF OBJECT_ID(N'v2.AFFAIRE') IS NULL
    CREATE TABLE v2.AFFAIRE (AFFRE_ID_AFFRE int NOT NULL PRIMARY KEY, AFFRE_ID_UTLST_CREATION int NULL, AFFRE_ID_UTLST_EN_COURS int NULL,
        AFFRE_DATE_CREATION datetime NOT NULL, AFFRE_LIBELLE varchar(70) NULL);

EXEC sp_executesql N'
INSERT INTO v2.MODE_PAIEMENT (R_MODEPAIEME_VALEUR, R_MODEPAIEME_LIBELLE_ECRAN, R_MODEPAIEME_UTILISABLE_SAISIE, R_MODEPAIEME_TYPE) VALUES
    (''L12CHQ'', ''Chèque (banc 12)'', 0, ''CH''),
    -- pas un cheque : son encaissement 2204004 n est pas liste, et son rejet est refuse
    (''L12ESPJ'', ''Espèces rejet (banc 12)'', 0, NULL);
-- Les clients : un actif (son adresse client pre-remplit le destinataire), un en sommeil (statut S), le client d attente
-- (compte 99999999) et le client des annulations (Client.cs:176-215).
SET IDENTITY_INSERT rec.Client ON;
INSERT INTO rec.Client (Id, Abrege, NumeroCompte, Nom, Type, Statut, Email, EstComptePc, EstCompteWeb) VALUES
    (2204201, ''L12CLIA'', ''411L12CLIA'', ''CLI REJET A'', ''C'', ''A'', ''cli.a@banc12.test'', 0, 0),
    (2204202, ''L12CLIS'', ''411L12CLIS'', ''CLI SOMMEIL'', ''C'', ''S'', NULL, 0, 0),
    (2204203, ''L12ATT'', ''99999999'', ''CLIENT ATTENTE BANC'', ''C'', ''A'', NULL, 0, 0),
    (2204204, ''L12ANN'', ''411L12ANN'', ''Client Divers Special ANNULATION'', ''D'', ''A'', NULL, 0, 0);
SET IDENTITY_INSERT rec.Client OFF;
INSERT INTO rec.ClientAdresse (IdClient, LigneAdresse, CodePostal, Localite, ParDefaut) VALUES (2204201, ''5 rue du Rejet'', ''69001'', ''LYON'', 1);
INSERT INTO v2.AFFAIRE (AFFRE_ID_AFFRE, AFFRE_DATE_CREATION, AFFRE_LIBELLE, AFFRE_ID_UTLST_EN_COURS) VALUES
    (2204301, DATEADD(DAY, -40, @aujourdhui), ''AFF REJET 12'', NULL),
    -- tenue par un utilisateur : l encaissement qui y est ventile ne se supprime pas (MenuEncaissement.cs:255-259)
    (2204302, DATEADD(DAY, -40, @aujourdhui), ''AFF REJET 12 VERROU'', 2204999);

INSERT INTO v2.ENCAISSEMENT (ENCMT_ID_ENCMT, ENCMT_MONTANT, ENCMT_DATE_ENCAISSEMENT, ENCMT_DESIGNATION_PAYEUR, ENCMT_NUMERO_TITRE, ENCMT_MODE_PAIEMENT,
    ENCMT_DESIGNATION_BANQUE, ENCMT_DATE_COMPTABILISATION, ENCMT_ID_ARRV, ENCMT_GUID) VALUES
    -- non comptabilise : le rejet le SUPPRIME avec sa ventilation (gestes, bloc 7)
    (2204001, 150.00, DATEADD(HOUR, 10, DATEADD(DAY, -10, @aujourdhui)), ''PAYEUR J12A'', ''J12CHQ01'', ''L12CHQ'', ''BANQUE J12'', NULL, NULL, NULL),
    -- comptabilise, deux ventilations dont une au client d attente : le rejet l ANNULE (gestes, bloc 8)
    (2204002, 80.00, DATEADD(HOUR, 10, DATEADD(DAY, -20, @aujourdhui)), ''PAYEUR J12B'', ''J12CHQ02'', ''L12CHQ'', ''BANQUE J12'', DATEADD(DAY, -15, @aujourdhui), 2204901, ''G12-0002''),
    -- ventile a un client en sommeil : liste, mais son rejet est refuse
    (2204003, 40.00, DATEADD(HOUR, 10, DATEADD(DAY, -5, @aujourdhui)), ''PAYEUR J12C'', ''J12CHQ03'', ''L12CHQ'', ''BANQUE J12'', NULL, NULL, NULL),
    -- ECARTE : pas un cheque -- jumeau retenu 2204003
    (2204004, 60.00, DATEADD(HOUR, 10, DATEADD(DAY, -7, @aujourdhui)), ''PAYEUR J12D'', ''J12ESP04'', ''L12ESPJ'', NULL, NULL, NULL, NULL),
    -- ventile a une affaire verrouillee : liste, mais son rejet est refuse
    (2204005, 25.00, DATEADD(HOUR, 10, DATEADD(DAY, -8, @aujourdhui)), ''PAYEUR J12E'', ''J12CHQ05'', ''L12CHQ'', ''BANQUE J12'', NULL, NULL, NULL),
    -- ECARTE : deja rejete (le rejet 2204401 au meme titre, meme date, meme montant) -- jumeau retenu 2204005
    (2204006, 90.00, DATEADD(HOUR, 10, DATEADD(DAY, -30, @aujourdhui)), ''PAYEUR J12F'', ''J12CHQ06'', ''L12CHQ'', ''BANQUE J12'', NULL, NULL, NULL);
INSERT INTO v2.VENTILATION (VENTI_ID_VENTI, VENTI_ID_PYEUR, VENTI_ID_ENCMT, VENTI_ID_AFFRE, VENTI_ID_CLIEN, VENTI_MONTANT, VENTI_DATE_VENTILATION) VALUES
    (2204101, NULL, 2204001, 2204301, 2204201, 150.00, DATEADD(DAY, -10, @aujourdhui)),
    (2204102, NULL, 2204002, 2204301, 2204201, 50.00, DATEADD(DAY, -20, @aujourdhui)),
    (2204103, NULL, 2204002, 2204301, 2204203, 30.00, DATEADD(DAY, -20, @aujourdhui)),
    (2204104, NULL, 2204003, 2204301, 2204202, 40.00, DATEADD(DAY, -5, @aujourdhui)),
    (2204105, NULL, 2204005, 2204302, 2204201, 25.00, DATEADD(DAY, -8, @aujourdhui));
INSERT INTO v2.ENCAISSEMENT_RECUS_REJETES (ENCRR_ID_ENCRR, ENCRR_NUM_TITRE, ENCRR_DATE_CREATION, ENCRR_DATE_ENCMT, ENCRR_MONTANT, ENCRR_RAISON_REJET,
    ENCRR_DESIGNATION_PAYEUR) VALUES
    (2204401, ''J12CHQ06'', DATEADD(DAY, -25, @aujourdhui), DATEADD(HOUR, 10, DATEADD(DAY, -30, @aujourdhui)), 90.00, ''Provision insuffisante'', ''PAYEUR J12F'');
',
    N'@aujourdhui datetime', @aujourdhui;
